import React, { HTMLAttributes } from 'react';

import { formatDistance } from '@helpers/formatHelper';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { IBaseRouteData } from '../@services/routes.service';
import { IRouteObject, RouteObjectType } from '../@types/routes.types';

interface IRoutePreviewHeaderProps extends HTMLAttributes<HTMLDivElement> {
  baseRouteData: IBaseRouteData;
  routeObjects: IRouteObject[];
}

const RoutePreviewHeader = ({ baseRouteData, routeObjects, ...rest }: IRoutePreviewHeaderProps) => {
  const data = React.useMemo(() => {
    let totalDistance = 0;
    let distanceInDistance = 0;

    routeObjects.forEach((routeObject) => {
      if (routeObject.type === RouteObjectType.Line) {
        if (routeObject.is_in_distance) distanceInDistance += routeObject.distance;
        totalDistance += routeObject.distance;
      }
    });

    return { totalDistance, distanceInDistance };
  }, [routeObjects]);
  return (
    <header {...rest}>
      <PohRow>
        <PohCol sm={2}>
          <strong className="text-success">{formatDistance(data.distanceInDistance)}</strong>
          <small className="text-muted d-block mt-n1">Дистанция</small>
        </PohCol>
      </PohRow>
    </header>
  );
};

export default RoutePreviewHeader;
